        if($isTeacher){$where[]='c.teacher_id=:teacher';$params['teacher']=$user['id'];}elseif($isCoordinator){$where[]='c.career_id=:career';$params['career']=$careerId;}elseif($role==='student'){if($studentId){$where[]='s.id=:student';$params['student']=$studentId;}else $where[]='1=0';}if($where)$sql.=' WHERE '.implode(' AND ',$where);$sql.=' ORDER BY ca.name,s.student_code,c.code,g.assessment_name';$q=$pdo->prepare($sql);$q->execute($params);$grades=$q->fetchAll();$gradeCourses=[];$gradesByStudent=[];
        foreach($grades as $g){$ck=(string)$g['course_id'];if($isTeacher||$role==='student'){$gradeCourses[$ck]['name']=$g['code'].' · '.$g['course_name'];$gradeCourses[$ck]['career']=$g['career_name'];$gradeCourses[$ck]['items'][]=$g;}else{$sk=(string)$g['student_id'];$gradesByStudent[$sk]['name']=$g['student_name'];$gradesByStudent[$sk]['code']=$g['student_code'];$gradesByStudent[$sk]['career']=$g['career_name'];$gradesByStudent[$sk]['courses'][$ck]['name']=$g['code'].' · '.$g['course_name'];$gradesByStudent[$sk]['courses'][$ck]['items'][]=$g;}}
    }
    if($page==='users'){$users=$pdo->query('SELECT u.*,r.name role,r.label role_label,c.name career_name FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN careers c ON c.id=u.career_id ORDER BY r.id,c.name,u.full_name')->fetchAll();$roles=$pdo->query('SELECT name,label FROM roles ORDER BY id')->fetchAll();}
} catch(Throwable $exception){error_log('EduCore page query: '.$exception->getMessage());$databaseError=true;}

$label=$roleLabels[$role]??'';$initials='';foreach(array_slice(preg_split('/\s+/',trim((string)$user['full_name']))?:[],0,2) as $part)$initials.=mb_substr($part,0,1,'UTF-8');
