><?php foreach($users as $u):?><tr data-search-row="users"><td><?=e($u['full_name'])?><small class="table-subline"><?=e($u['email'])?></small></td><td><?=e($u['role_label'])?></td><td><?=e($u['career_name']?:'—')?></td><td><?=e($u['status'])?></td><?php if($isSystemAdmin):?><td><?php if((int)$u['id']!==(int)$user['id']):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="user_status"><input type="hidden" name="return_page" value="users"><input type="hidden" name="user_id" value="<?=(int)$u['id']?>"><button class="button-secondary button-small" type="submit"><?=$u['status']==='active'?'Desactivar':'Activar'?></button></form><?php endif;?></td><?php endif;?></tr><?php endforeach;?></tbody></table></div></article><?php endif;?>
